-- ============================================================================
-- IMPACT FULL SEED (Railway-ready — one INSERT per row)
-- Requires IDENTITY columns (GENERATED BY DEFAULT AS IDENTITY).
-- Paste this whole file into Railway Data console and Run.
-- Safe to re-run: truncates app tables and resets identity sequences.
-- ============================================================================
BEGIN;

TRUNCATE TABLE campaign_photo, attendance, application, progress, campaign, "user", category, college RESTART IDENTITY CASCADE;

-- 1) COLLEGES (1-6)

-- 2) CATEGORIES (1-8)

-- 3) USERS (1-30) — 5 per college

-- 4) CAMPAIGNS (1-15) — columns: campaign_id, created_at, description, end_date, location, max_volunteers, published_at, start_date, status, title, updated_at, approved_by_id, category_id, managed_by_id, proposed_by_id

-- 5) PROGRESS (1-7)

-- 6) APPLICATIONS (1-40)

-- 7
-- ) ATTENDANCE (1-53)

-- 8) Bump identity sequences past the highest manually inserted ID
SELECT setval(pg_get_serial_sequence('college',     'college_id'),    (SELECT MAX(college_id)    FROM college),     true);
SELECT setval(pg_get_serial_sequence('category',    'category_id'),   (SELECT MAX(category_id)   FROM category),    true);
SELECT setval(pg_get_serial_sequence('"user"',      'user_id'),       (SELECT MAX(user_id)       FROM "user"),      true);
SELECT setval(pg_get_serial_sequence('campaign',    'campaign_id'),   (SELECT MAX(campaign_id)   FROM campaign),    true);
SELECT setval(pg_get_serial_sequence('progress',    'progress_id'),   (SELECT MAX(progress_id)   FROM progress),    true);
SELECT setval(pg_get_serial_sequence('application', 'id'),            (SELECT MAX(id)            FROM application), true);
SELECT setval(pg_get_serial_sequence('attendance',  'attendance_id'), (SELECT MAX(attendance_id) FROM attendance),  true);

COMMIT;

-- Verify counts
SELECT 'colleges'     AS table_name, COUNT(*) AS rows FROM college
UNION ALL SELECT 'categories',   COUNT(*) FROM category
UNION ALL SELECT 'users',        COUNT(*) FROM "user"
UNION ALL SELECT 'campaigns',    COUNT(*) FROM campaign
UNION ALL SELECT 'progress',     COUNT(*) FROM progress
UNION ALL SELECT 'applications', COUNT(*) FROM application
UNION ALL SELECT 'attendance',   COUNT(*) FROM attendance;
